import React, { useState, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    login({ email, role: email.includes('admin') ? 'admin' : 'student' });
    navigate('/dashboard');
  };

  return (
    <div className="min-h-screen bg-[#0A0E1A] flex items-center justify-center p-4">
      <div className="w-full max-w-sm">
        <div className="flex items-center gap-2.5 justify-center mb-8">
          <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-blue-500 to-cyan-400 flex items-center justify-center font-black text-[#0A0E1A] text-lg shadow-lg shadow-blue-500/20">A</div>
          <span className="text-lg font-extrabold tracking-tight text-white">AVALON <span className="text-blue-400 font-medium">SECURE</span></span>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-8 shadow-xl">
          <h2 className="text-white font-bold text-lg mb-6 text-center">Connexion</h2>
          <form onSubmit={handleSubmit} className="space-y-3">
            <input
              type="email"
              placeholder="Email"
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-2.5 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors"
            />
            <input
              type="password"
              placeholder="Mot de passe"
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 text-white px-4 py-2.5 rounded-lg text-sm outline-none focus:border-blue-500 transition-colors"
            />
            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-500 text-white font-semibold py-2.5 rounded-lg text-sm transition-colors mt-2">
              Valider
            </button>
          </form>
        </div>

        <p className="text-center text-slate-500 text-xs mt-6">
          Pas encore de compte ? <Link to="/register" className="text-blue-400 hover:text-blue-300 font-semibold">S'inscrire</Link>
        </p>
      </div>
    </div>
  );
};
export default Login;
